RES = [("db", 5000000, 12000), ("file", 800, 1), ("db", 2000000, 4000), ("file", 1500, 1)]
census = {}
for kind, size, n in RES:
    c = census.setdefault(kind, {"bytes": 0, "records": 0, "n": 0})
    c["bytes"] += size; c["records"] += n; c["n"] += 1
for kind, c in census.items():
    print("%s: %d resources, %d bytes, %d records" % (kind, c["n"], c["bytes"], c["records"]))

