RESOURCES = {"db1": "open", "db2": "credentialed", "db3": "embargoed"}
def probe(name):
    return RESOURCES.get(name, "unknown")
readable = [n for n in RESOURCES if probe(n) in ("open", "credentialed")]
print("readable:", readable)

